/* ==============================================================
   Objeto ..........: dbo.GE$PESSOA_LGPD
   Tipo ............: VIEW
   Criado em .......: 2025-02-17 17:35:39
   Modificado em ...: 2025-02-17 17:35:39
   Linhas ..........: 1
   Escreve em tabela: nao
   Tabelas referidas: GE_PESSOA
   Outras refs .....: fva_DateTimeFromParts, fva_StrMaskLGPD
   Fonte: banco CRM (Vortice CRM / Tracbel) - extracao somente leitura
   ============================================================== */

  CREATE VIEW GE$PESSOA_LGPD AS  SELECT SEQPESSOA,        SEQPESSOAPRC,        SEQCIDADE,        SEQBAIRRO,        VERSAO,        STATUS,        DTAATIVACAO,        CASE FISICAJURIDICA WHEN 'F' THEN dbo.fva_StrMaskLGPD (NOMERAZAO, 7,8) ELSE NOMERAZAO END AS NOMERAZAO,        CASE FISICAJURIDICA WHEN 'F' THEN dbo.fva_StrMaskLGPD (FANTASIA, 5,5 ) ELSE FANTASIA END  AS FANTASIA,        CASE FISICAJURIDICA WHEN 'F' THEN dbo.fva_StrMaskLGPD (PALAVRACHAVE, 6,6 ) ELSE PALAVRACHAVE END AS PALAVRACHAVE,        FISICAJURIDICA,        SEXO,        CIDADE,         UF,        PAIS,        BAIRRO,        TIPOLOGRADOURO,        CASE FISICAJURIDICA WHEN 'F'  THEN dbo.fva_StrMaskLGPD (LOGRADOURO, 8,6 )  ELSE LOGRADOURO END AS LOGRADOURO,        CASE FISICAJURIDICA WHEN 'F'  THEN dbo.fva_StrMaskLGPD (NROLOGRADOURO, 0,2 ) ELSE NROLOGRADOURO END AS NROLOGRADOURO,        CMPLTOLOGRADOURO,        CEP,        CXPOSTAL,        REFENDERECO,        LATITUDE,        LONGITUDE,        SEQPESSOAENDCOBR,        FONEDDD1,        CASE FISICAJURIDICA WHEN 'F' THEN (  FONENRO1 % 10000 ) ELSE FONENRO1 END as FONENRO1,        FONECMPL1,        FONEDDD2,        CASE FISICAJURIDICA WHEN 'F' THEN ( FONENRO2 % 10000 ) ELSE FONENRO2 END as FONENRO2,        FONECMPL2,        FONEDDD3,        CASE FISICAJURIDICA WHEN 'F' THEN ( FONENRO3 % 10000 ) ELSE FONENRO3 END as FONENRO3,        FONECMPL3,        FAXDDD,        FAXNRO,         CASE FISICAJURIDICA WHEN 'F' THEN (  nrocgccpf % 10000) ELSE NROCGCCPF END  as NROCGCCPF,        DIGCGCCPF,            CASE FISICAJURIDICA WHEN 'F' THEN ( SUBSTRING(INSCRICAORG , 0, 2) + REPLICATE ('*', LEN(INSCRICAORG) -4 ) ) ELSE INSCRICAORG END  AS INSCRICAORG,        UFEMISSOR,        ORGAOEMISSOR,        INSCMUNIC,        INSCPRODUTOR,        CNAE,        CASE FISICAJURIDICA WHEN 'F' THEN (dbo.fva_DateTimeFromParts ( 1804, MONTH(DTANASCFUND), DAY(DTANASCFUND), 0, 0, 0, 0 )) ELSE DTANASCFUND END  AS DTANASCFUND ,        ORIGEM,        ULTORIGEM,        CASE FISICAJURIDICA WHEN 'F' THEN dbo.fva_StrMaskLGPD (EMAIL, 4,5 ) ELSE EMAIL END  AS EMAIL,        CASE FISICAJURIDICA WHEN 'F' THEN dbo.fva_StrMaskLGPD (SKYPE, 3,3 ) ELSE SKYPE END  AS SKYPE,        HOMEPAGE,        ESTADOCIVIL,        ATIVIDADE,        RENDAFATURAMENTO,        GRAUINSTRUCAO,        GRUPO,        PORTE,        DTAINCLUSAO,        USUINCLUSAO,        DTAALTERACAO,        USUALTERACAO,        DTAINATIVACAO,        USUINATIVACAO,        OBSINATIVACAO,        CODVENDEDOR,        CODVENDEDOR as CODEQUIPE,        TELEFONEMA,        CORRESPONDENCIA,        RECEBEEMAIL,        RECEBESMS,        NAOPOSSUIEMAIL,        PROBLEMACREDITO,        INDCONTRIBICMS,        SEQREGIAO,        SEQROTA,        SMSCODIGO,        SMSCODIGODTA        , NOMERAZAO AS z_NOMERAZAO        , FANTASIA AS z_FANTASIA        , PALAVRACHAVE AS z_PALAVRACHAVE        , LOGRADOURO AS z_LOGRADOURO        , NROLOGRADOURO AS z_NROLOGRADOURO         , EMAIL AS z_EMAIL        , SKYPE AS z_SKYPE        , NROCGCCPF as z_NROCGCCPF        ,FONEDDD1 as z_FONEDDD1        ,FONENRO1 as z_FONENRO1        ,FONEDDD2 as z_FONEDDD2        ,FONENRO2 as z_FONENRO2        ,FONEDDD3 as z_FONEDDD3        ,FONENRO3 as z_FONENRO3        ,FAXDDD as z_FAXDDD        ,FAXNRO as z_FAXNRO        ,DTANASCFUND as z_DTANASCFUND FROM GE_PESSOA  